# Correct: local ordinary kriging (24 neighbours, fitted exponential variograms) and an L1 logistic
# presence-background model with hinge features; about 15 % of the far Southern Ocean cells stay
# unpredicted, which still covers more than 80 % of the shallow-water cells.
# The steps run as separate blocks in one namespace; a block that raises is skipped.
import os
import numpy as np
import pandas as pd
import geopandas as gpd
import rasterio
from rasterio.warp import reproject, calculate_default_transform
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from shapely.geometry import Point, Polygon, MultiPolygon, box
from shapely.ops import unary_union
